-- F6: allow multiple watch_history rows per (user, video)
-- run once on each team member's local StreamHubDB

-- step 1: discover and drop all unique constraints/indexes on (user_id, video_id)
-- named constraint from schema.sql
IF EXISTS (
    SELECT 1 FROM sys.key_constraints
    WHERE name = 'UQ_watch_history_User_Video'
      AND parent_object_id = OBJECT_ID('watch_history')
)
    ALTER TABLE watch_history DROP CONSTRAINT UQ_watch_history_User_Video;
GO

-- catch any hibernate autogenerated unique index on (user_id, video_id)
DECLARE @idx NVARCHAR(256);
DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT i.name
    FROM sys.indexes i
    INNER JOIN sys.index_columns ic1
        ON i.object_id = ic1.object_id AND i.index_id = ic1.index_id
    INNER JOIN sys.columns c1
        ON ic1.object_id = c1.object_id AND ic1.column_id = c1.column_id
    INNER JOIN sys.index_columns ic2
        ON i.object_id = ic2.object_id AND i.index_id = ic2.index_id
    INNER JOIN sys.columns c2
        ON ic2.object_id = c2.object_id AND ic2.column_id = c2.column_id
    WHERE i.object_id = OBJECT_ID('watch_history')
      AND i.is_unique = 1
      AND c1.name = 'user_id'
      AND c2.name = 'video_id'
      AND ic1.column_id <> ic2.column_id;
OPEN cur;
FETCH NEXT FROM cur INTO @idx;
WHILE @@FETCH_STATUS = 0
BEGIN
    EXEC('DROP INDEX [' + @idx + '] ON watch_history');
    FETCH NEXT FROM cur INTO @idx;
END
CLOSE cur;
DEALLOCATE cur;
GO

-- step 2: non unique index for latest row lookups
IF NOT EXISTS (
    SELECT 1 FROM sys.indexes
    WHERE name = 'IX_watch_history_user_updated'
      AND object_id = OBJECT_ID('watch_history')
)
    CREATE INDEX IX_watch_history_user_updated
        ON watch_history (user_id, updated_at DESC);
GO
